class SQL {
    private java.util.Map<String, java.util.List<java.util.List<String>>> tables = new java.util.HashMap<>();
    public SQL(java.util.List<String> names, java.util.List<Integer> columns) {
        for (String name : names) tables.put(name, new java.util.ArrayList<>());
    }
    public void insertRow(String name, java.util.List<String> row) {
        tables.get(name).add(row);
    }
    public String selectCell(String name, int rowId, int columnId) {
        return tables.get(name).get(rowId - 1).get(columnId - 1);
    }
}

import java.util.*;

class SQL {
    private Map<String, Map<Integer, List<String>>> tables;
    private Map<String, Integer> nextId;
    public SQL(List<String> names, List<Integer> columns) {
        tables = new HashMap();
        nextId = new HashMap();
        for (int i = 0; i < names.size(); i++) {
            tables.put(names.get(i), new HashMap());
            nextId.put(names.get(i), 1);
        }
    }
    public void insertRow(String name, List<String> row) {
        int id = nextId.get(name).intValue();
        tables.get(name).put(id, row);
        nextId.put(name, id + 1);
    }
    public String selectCell(String name, int rowId, int columnId) {
        return tables.get(name).get(rowId).get(columnId - 1);
    }
}
